export function renderAtlasDemo(l,value,art,esc){
 const d=l.demo,a=d.states.find(x=>x.value===value)||d.states[0],v=a.value;let scene='';
 const node=(name,cls='')=>`<span class="observe-node ${cls}">${name}</span>`,arrow='<i class="observe-arrow">⟶</i>';
 switch(d.scene){
 case'time':scene=`<div class="observe-time"><span>过去</span><b>现在参照 ●</b><span>将来</span><div class="observe-time-line"></div>${v==='habit'?'<div class="repeat-marks">↻　↻　↻　↻<small>每周重复</small></div>':'<div class="live-ring">●<small>正在进行</small></div>'}</div>`;break;
 case'world':scene=`<div class="observe-world"><article>${node('现实')}<p>Mia 不在这里</p><strong>在别处</strong></article><article class="${v==='wish'?'dream-on':''}">${node('愿望气泡')}<p>但愿 Mia 在这里</p><strong>${v==='wish'?'♡ 希望不同':'点击另一种观察'}</strong></article></div>`;break;
 case'agreement':scene=`<div class="observe-baskets">${Array.from({length:v==='one'?1:3},()=>'<span class="observe-basket">♧ ♧ ♧<small>basket</small></span>').join('')}${arrow}${node(v==='one'?'is':'are','verb-controller')}</div><p class="observe-mini">篮子的数量控制动词，内部的花不抢指挥棒。</p>`;break;
 case'passive':scene=`<div class="observe-event">${node('Mia',v==='agent'?'focus-node':'')}${arrow}${node('sign',v==='patient'?'focus-node':'')}</div><p class="observe-mini">动作方向始终 Mia → sign；金框只表示句子起点。</p>`;break;
 case'space':scene=`<div class="observe-space ${v}"><div class="observe-box">BOX</div><span class="observe-star">★</span>${v==='enter'?'<span class="observe-path">外　⟶　内</span>':'<span class="observe-path">静止在内部</span>'}</div>`;break;
 case'clause':scene=v==='direct'?'<div class="observe-chips"><b>Where</b><b>does</b><b>Mia</b><b>live?</b></div><p class="observe-mini">直接提问</p>':'<div class="observe-chips"><b>I know</b><span class="observe-capsule"><b>where</b><b>Mia</b><b>lives</b></span></div><p class="observe-mini">外部：know 的宾语；内部：Mia lives</p>';break;
 case'relative':scene=v==='identify'?'<div class="observe-candidates"><span>助手 ○</span><strong>红衣助手 ●</strong><span>助手 ○</span></div><p class="observe-mini">线索帮助辨认其中一位</p>':'<div class="observe-event"><span>Mia</span><b class="observe-comma">,</b><span class="observe-note">who is our guide</span><b class="observe-comma">,</b></div><p class="observe-mini">已经明确的人物，添加旁注</p>';break;
 case'logic':scene=`<div class="observe-event">${node(v==='cause'?'已经下雨':'会下雨吗？')}${arrow}${node(v==='cause'?'因此进屋':'若下雨才进屋')}</div><div class="observe-logic ${v}">${v==='cause'?'已给出的原因':'?　条件尚不保证发生'}</div>`;break;
 case'compare':{const data=v==='height'?[5,3]:[2,5];scene=`<div class="observe-bars">${['Mia','Leo'].map((n,i)=>`<article><div style="height:${data[i]*18}px"><strong>${data[i]}</strong></div><span>${n}</span></article>`).join('')}</div><p class="observe-mini">${v==='height'?'身高示意格':'书本数量'} · 只比较当前维度</p>`;break;}
 case'activity':scene=`<div class="observe-event">${node(v==='content'?'job 的内容':'Mia 的动作')}${arrow}<span class="activity-orb ${v}">painting signs</span></div><p class="observe-mini">${v==='content'?'活动作为工作内容，不保证此刻在做':'进行结构描述此刻动作'}</p>`;break;
 case'purpose':scene=`<p class="observe-mini">愿望中的内容，不保证已经实现</p><div class="observe-event">${node(v==='active'?'Mia 来搬':'有人来搬')}${arrow}${node('sign')}</div><p class="observe-mini">${v==='active'?'Mia 是搬运参与者':'sign 是受到搬运的对象；Mia 表达愿望'}</p>`;break;
 case'participle':scene=`<div class="observe-event">${node(v==='source'?'Mia 的讲解':'演出')}${arrow}${node(v==='source'?'访客感到兴奋':'Mia 感到兴奋')}</div><p class="observe-mini">${v==='source'?'exciting：引起感受':'excited：体验感受'}</p>`;break;
 case'reduce':scene=`<div class="observe-chips"><b>Mia can sing</b><b>and Leo can</b><b class="${v==='short'?'faded-word':''}">sing</b><b>too.</b></div><p class="observe-mini">${v==='short'?'第二个 sing 可恢复，can 和 too 保留':'两人都具备唱歌能力'}</p>`;break;
 }
 return `<div id="lesson-demo" class="lesson-demo atlas-demo" data-value="${v}"><div class="demo-top"><strong>观察小实验 · 不计分</strong><span>先停下观察，再播放示意</span></div><div class="demo-controls">${d.states.map((x,i)=>`<button data-action="lesson-demo" data-value="${x.value}" aria-pressed="${v===x.value}" class="${v===x.value?'selected':''}">${i+1} · ${esc(x.label)}</button>`).join('')}<button data-action="demo-motion" aria-pressed="false">▶ 播放示意</button></div><div class="observation-frame paused scene-${d.scene} state-${v}">${scene}</div><p lang="en">${esc(a.text)}</p><p>${esc(a.note)}</p><button class="sound-button" data-action="speak" data-text="${esc(a.text)}">♫ 听这句话</button></div>`;
}
export function renderEditor(q,l,locked,esc){const s=l.settings,off=locked?'disabled':'';return `<div class="editor-desk"><div class="editor-original"><small>原稿与需要保留的意思</small><p lang="en">${esc(q.original)}</p><div class="editor-parts">${q.parts.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><div class="editor-arrow">↓ 按任务改写，再核对证据</div><div class="editor-draft ${s.version?'drafted':''}"><small>你的候选稿 · 尚须检查</small><p lang="en">${esc(s.version||'先选择一份候选稿')}</p></div><div class="editor-proof"><small>你选择的核对证据</small><p>${esc(s.evidence||'再选择保留了什么')}</p></div>${Object.entries(q.axes).map(([axis,items])=>`<fieldset><legend>${axis==='version'?'① 选符合原意与任务的候选稿':'② 选择正确的核对证据'}</legend>${items.map(([v,t])=>`<button data-action="lab-direct" data-axis="${axis}" data-value="${esc(v)}" aria-pressed="${s[axis]===v}" class="${s[axis]===v?'selected':''}" ${off}>${esc(t)}</button>`).join('')}</fieldset>`).join('')}<button class="primary" data-action="check-lab" ${locked||!s.version||!s.evidence?'disabled':''}>核对稿件与证据 ✓</button><p class="interaction-tip">不按句子长短判对错；这题只核对给定的候选方案。</p></div>`;}
export function renderQuestTrail(chapter,done,esc){if(chapter.kind!=='integrated')return '';const total=chapter.missions.length,complete=chapter.missions.filter(m=>done.includes(m.id)).length;return `<section class="quest-trail" aria-label="庆典故事进度"><div><strong>开园庆典 · ${complete} / ${total} 幕完成</strong><p>${complete===total?'整场冒险已走完。可以重玩，试着先自己解释再看反馈。':'每一幕解决一个真实表达任务，可按顺序玩，也能先回顾感兴趣的部分。'}</p></div><div class="quest-stops">${chapter.missions.map((m,i)=>`<button data-action="play" data-id="${m.id}" class="${done.includes(m.id)?'finished':''}" aria-label="${esc(m.title)}">${done.includes(m.id)?'✓':i+1}</button>`).join('')}</div></section>`;}
